CREATE TABLE users
(
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Email" text NOT NULL,
    "GoogleId" text NOT NULL,
    "Name" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_users" PRIMARY KEY ("Id")
);

CREATE TABLE refresh_tokens
(
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "HashedToken" text NOT NULL,
    "UserId" integer NOT NULL,
    "ExpiresAt" timestamp with time zone NOT NULL,
    "IsRevoked" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_refresh_tokens" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_refresh_tokens_users_UserId"
        FOREIGN KEY ("UserId") REFERENCES users ("Id") ON DELETE CASCADE
);

CREATE UNIQUE INDEX "IX_refresh_tokens_HashedToken"
    ON refresh_tokens ("HashedToken");

CREATE INDEX "IX_refresh_tokens_UserId"
    ON refresh_tokens ("UserId");

CREATE UNIQUE INDEX "IX_users_Email"
    ON users ("Email");

CREATE UNIQUE INDEX "IX_users_GoogleId"
    ON users ("GoogleId");
